const games = window.RATIKA_GAMES;
const grid = document.querySelector('#game-grid');
const dialog = document.querySelector('#game-dialog');
games.forEach((game, index) => {
  const button = document.createElement('button');
  button.className = 'game-card';
  button.setAttribute('aria-label', `Conocer ${game.title}`);
  const artwork = document.createElement('div');
  artwork.className = 'card-art';
  const img = document.createElement('img');
  img.src = game.image;
  img.alt = `Ilustración de ${game.title}`;
  img.loading = 'lazy';
  img.width = 1300;
  img.height = 1300;
  const label = document.createElement('span');
  label.className = 'card-tag';
  label.textContent = 'UNIVERSO RATIKA';
  artwork.append(img, label);
  const info = document.createElement('div');
  info.className = 'card-info';
  const text = document.createElement('div');
  const subtitle = document.createElement('p');
  subtitle.textContent = game.subtitle;
  const title = document.createElement('h3');
  title.textContent = game.title;
  const more = document.createElement('span');
  more.className = 'card-more';
  more.textContent = '+';
  more.setAttribute('aria-hidden', 'true');
  text.append(subtitle, title);
  info.append(text, more);
  button.append(artwork, info);
  button.addEventListener('click', () => {
    document.querySelector('#dialog-title').textContent = game.title;
    document.querySelector('#dialog-description').textContent = game.description;
    const image = document.querySelector('#dialog-image');
    image.src = game.image;
    image.alt = `Ilustración de ${game.title}`;
    const store = document.querySelector('#dialog-store');
    let safeUrl = '';
    try { const url = new URL(game.storeUrl); if (url.protocol === 'https:') safeUrl = url.href; } catch {}
    store.hidden = !safeUrl;
    store.textContent = game.storeLabel || 'Visitar página del juego';
    if (safeUrl) store.href = safeUrl; else store.removeAttribute('href');
    document.querySelector('#dialog-pending').hidden = Boolean(safeUrl);
    dialog.showModal();
    document.body.classList.add('modal-open');
  });
  grid.append(button);
});
document.querySelector('.dialog-close').addEventListener('click', () => dialog.close());
dialog.addEventListener('close', () => document.body.classList.remove('modal-open'));
dialog.addEventListener('click', event => { if (event.target === dialog) { const rect = dialog.getBoundingClientRect(); if (event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom) dialog.close(); } });
const menu = document.querySelector('.menu-toggle');
const navigation = document.querySelector('#navigation');
function closeMenu() { menu.setAttribute('aria-expanded', 'false'); navigation.classList.remove('is-open'); }
menu.addEventListener('click', () => { const open = menu.getAttribute('aria-expanded') !== 'true'; menu.setAttribute('aria-expanded', String(open)); navigation.classList.toggle('is-open', open); });
navigation.querySelectorAll('a').forEach(link => link.addEventListener('click', closeMenu));
document.addEventListener('keydown', event => { if (event.key === 'Escape') closeMenu(); });
const video = document.querySelector('#ratika-video');
const videoToggle = document.querySelector('#video-toggle');
videoToggle.addEventListener('click', async () => { if (video.paused) { try { await video.play(); } catch { videoToggle.textContent = 'Reintentar animación'; } } else video.pause(); });
video.addEventListener('play', () => { videoToggle.textContent = 'Pausar animación'; });
video.addEventListener('pause', () => { videoToggle.textContent = 'Reproducir animación'; });
document.querySelector('#year').textContent = new Date().getFullYear();
